      "angle": "从穿着体验和足部支撑切入，再讲静音防滑与打理便携。",
      "blocks": [
        {
          "stage": "welcome",
          "focus": "开场互动",
          "sentences": [
            {
              "display_text": "欢迎来到直播间，今天咱们聊聊脚上这双拖鞋。",
              "spoken_text": "欢迎来到直播间，今天咱们聊聊脚上这双拖鞋。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "姐妹平时在家走动多，还是坐着多？脚底累不累？",
              "spoken_text": "姐妹平时在家走动多，还是坐着多？脚底累不累？",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "pain",
          "focus": "久站脚底累、选拖鞋难",
          "sentences": [
            {
              "display_text": "有没有这种感觉：在厨房站一会儿，脚底又酸又胀。",
              "spoken_text": "有没有这种感觉：在厨房站一会儿，脚底又酸又胀。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "想找一双能撑住脚、走起来又轻松的拖鞋，不容易。",
              "spoken_text": "想找一双能撑住脚、走起来又轻松的拖鞋，不容易。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "identity",
          "focus": "商品身份",
          "sentences": [
            {
              "display_text": "这是 Joy Share 生活选物的足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款。",
              "spoken_text": "这是 Joy Share 生活选物的足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款。",
              "kind": "product_claim",
              "fact_ids": ["NAME", "SELLING"]
            },
            {
              "display_text": "专门按女性足部曲线来做的，上脚就能感受到不一样。",
              "spoken_text": "专门按女性足部曲线来做的，上脚就能感受到不一样。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "足弓支撑与厚底软弹",
          "sentences": [
            {
              "display_text": "它里面有足弓支撑，脚心位置被轻轻托住。",
              "spoken_text": "它里面有足弓支撑，脚心位置被轻轻托住。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "比如你站在水槽前洗菜，站久了脚心容易空、容易累。",
              "spoken_text": "比如你站在水槽前洗菜，站久了脚心容易空、容易累。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "有支撑之后，脚底受力更均匀，缓解久站带来的压力，走起来软弹缓震。",
              "spoken_text": "有支撑之后，脚底受力更均匀，缓解久站带来的压力，走起来软弹缓震。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "EVA 一体成型与小蛮腰厚底",
          "sentences": [
            {
              "display_text": "材质是优选 E V A 环保材质，一体成型。",
              "spoken_text": "材质是优选 E V A 环保材质，一体成型。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "一体成型的好处是，鞋身没有拼接缝，整体更利落。",
              "spoken_text": "一体成型的好处是，鞋身没有拼接缝，整体更利落。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "小蛮腰厚底设计，视觉上修饰脚型，穿上显脚瘦，还耐磨。",
              "spoken_text": "小蛮腰厚底设计，视觉上修饰脚型，穿上显脚瘦，还耐磨。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "静音防滑与居家走动",
          "sentences": [
            {
              "display_text": "鞋底有静音和防滑特性。",
              "spoken_text": "鞋底有静音和防滑特性。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "晚上家人睡了，你起来倒水，走路声音小，减少打扰。",
              "spoken_text": "晚上家人睡了，你起来倒水，走路声音小，减少打扰。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "浴室潮湿地面行走时多留个心，防滑是加分项，安全还得自己注意。",
              "spoken_text": "浴室潮湿地面行走时多留个心，防滑是加分项，安全还得自己注意。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "轻便、快干、防臭与易清洗",
          "sentences": [
            {
              "display_text": "整双鞋很轻便，出门旅行塞进行李箱不占地方。",
              "spoken_text": "整双鞋很轻便，出门旅行塞进行李箱不占地方。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "材质防臭快干，一冲即净，浴室穿完冲一下挂起来就好。",
              "spoken_text": "材质防臭快干，一冲即净，浴室穿完冲一下挂起来就好。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "去海边沙滩漫步，沾了沙用水一冲，省心得很。",
              "spoken_text": "去海边沙滩漫步，沾了沙用水一冲，省心得很。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
