          "stage": "scene",
          "focus": "多场景适用",
          "sentences": [
            {
              "display_text": "居家室内、浴室洗澡、旅行出游都能穿。",
              "spoken_text": "居家室内、浴室洗澡、旅行出游都能穿。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
